279	/// Create the struct definition itself.
280	fn create_struct(element: &Elem) -> TokenStream {
281	    let Elem { vis, ident, docs, .. } = element;
282	
283	    let debug = element.cannot("Debug").then(|| quote! { Debug, });
284	    let fields = element.struct_fields().map(create_field);
285	    let oneliner = oneliner(docs);
