336	/// Create the `new` function for the element.
337	fn create_new_func(element: &Elem) -> TokenStream {
338	    let params = element
339	        .struct_fields()
340	        .filter(|field| field.required)
341	        .map(|Field { ident, ty, .. }| quote! { #ident: #ty });
342	
343	    let fields = element.struct_fields().map(|field| {
344	        let ident = &field.ident;
345	        if field.required {
346	            quote! { #ident }
347	        } else if field.synthesized {
348	            quote! { #ident: None }
349	        } else {
350	            quote! { #ident: #foundations::Settable::new() }
351	        }
352	    });
353	
354	    quote! {
355	        /// Create a new instance of the element.
356	        pub fn new(#(#params),*) -> Self {
357	            Self { #(#fields,)* }
358	        }
359	    }
360	}
